    19	import org.slf4j.Logger;
    20	import org.slf4j.LoggerFactory;
    21	import org.springframework.samples.petclinic.model.Owner;
    22	import org.springframework.samples.petclinic.util.MembershipNumberFormatter;
    23	import org.springframework.samples.petclinic.util.OwnerMembership;
    24	import org.springframework.stereotype.Component;
    25	
    26	/**
    27	 * Emits audit records for owner lifecycle events to the dedicated {@code AUDIT} logger,
    28	 * keeping audit-trail concerns out of the business logic that triggers them.
    29	 */
    30	@Component
    31	public class OwnerAuditLogger {
    32	
    33	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
    34	
    35	    /**
    36	     * Record that an owner was successfully created, capturing its id, customer code,
    37	     * registration date, membership level and membership number.
    38	     *
    39	     * @param owner the persisted owner (with its generated id) to audit
    40	     */
    41	    public void ownerCreated(Owner owner) {
    42	        AUDIT.info(
    43	            "Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
    44	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
    45	            membershipLevel(owner), membershipNumber(owner));
    46	    }
    47	
    48	    private static int membershipLevel(Owner owner) {
    49	        return OwnerMembership.level(owner);
    50	    }
    51	
    52	    private static String membershipNumber(Owner owner) {
    53	        return MembershipNumberFormatter.format(owner.getCustomerCode(), owner.getRegistrationDate());
    54	    }
    55	}
