    17	package org.springframework.samples.petclinic.util;
    18	
    19	import java.util.function.Predicate;
    20	
    21	/**
    22	 * Builds and parses an owner's {@code customerCode}, a stable {@code "<REGION>-<HASH8>"} identity
    23	 * where {@code REGION} is the owner's region and {@code HASH8} is the first eight upper-case hex
    24	 * characters of SHA-256 over the normalized telephone concatenated with the last name.
    25	 */
    26	public final class CustomerCodeGenerator {
    27	
    28	    /** Separator between the region prefix and the hash suffix. */
    29	    private static final String SEPARATOR = "-";
    30	
    31	    /** Number of upper-case hex characters kept from the digest. */
    32	    private static final int HASH_LENGTH = 8;
    33	
    34	    private CustomerCodeGenerator() {
    35	    }
    36	
    37	    /**
    38	     * Format a customer code as {@code "<REGION>-<HASH8>"} (for example {@code "NSW-1A2B3C4D"}),
    39	     * where {@code HASH8} is the first eight upper-case hex characters of
    40	     * {@code SHA-256(normalizedTelephone + lastName)}.
    41	     *
    42	     * @param region              the owner's region
    43	     * @param normalizedTelephone the owner's normalized (E.164) telephone
    44	     * @param lastName            the owner's last name
    45	     * @return the formatted customer code
    46	     */
    47	    public static String format(String region, String normalizedTelephone, String lastName) {
    48	        return region + SEPARATOR + hash8(normalizedTelephone, lastName);
    49	    }
    50	
    51	    /**
    52	     * De-duplicate a formatted customer code against the codes already in use. When {@code baseCode}
    53	     * is free it is returned unchanged; otherwise {@code "-<n>"} is appended using the smallest
    54	     * {@code n >= 2} that yields a code {@code isTaken} reports as free.
    55	     *
    56	     * @param baseCode the freshly formatted customer code (see {@link #format})
    57	     * @param isTaken  tests whether a candidate code already belongs to another owner
    58	     * @return a customer code that {@code isTaken} reports as free
    59	     */
    60	    public static String deduplicate(String baseCode, Predicate<String> isTaken) {
    61	        if (!isTaken.test(baseCode)) {
    62	            return baseCode;
    63	        }
    64	        for (int n = 2; ; n++) {
    65	            String candidate = baseCode + SEPARATOR + n;
    66	            if (!isTaken.test(candidate)) {
    67	                return candidate;
    68	            }
    69	        }
    70	    }
    71	
    72	    /**
    73	     * Extract the {@code REGION} prefix from a customer code produced by {@link #format}.
    74	     *
    75	     * @param customerCode the customer code, may be {@code null}
    76	     * @return the region prefix, or {@code null} when the customer code is {@code null}
    77	     */
    78	    public static String region(String customerCode) {
    79	        if (customerCode == null) {
    80	            return null;
    81	        }
    82	        int separator = customerCode.indexOf(SEPARATOR);
    83	        return separator < 0 ? customerCode : customerCode.substring(0, separator);
    84	    }
    85	
    86	    private static String hash8(String normalizedTelephone, String lastName) {
    87	        String key = orEmpty(normalizedTelephone) + orEmpty(lastName);
    88	        return Sha256.hex(key).substring(0, HASH_LENGTH).toUpperCase();
    89	    }
    90	
    91	    private static String orEmpty(String value) {
    92	        return value == null ? "" : value;
    93	    }
    94	}
