    19	/**
    20	 * Maps an owner's {@code membershipPoints} to their {@code membershipLevel}.
    21	 */
    22	public final class MembershipLevelFormatter {
    23	
    24	    private MembershipLevelFormatter() {
    25	    }
    26	
    27	    /**
    28	     * Return the membership level derived from the given membership points: level 1 for 0-1 points,
    29	     * 2 for 2-3 points, 3 for 4-5 points and 4 for 6 or more points.
    30	     *
    31	     * @param points the owner's membership points, as produced by {@link MembershipPointsFormatter}
    32	     * @return the membership level, between 1 and 4
    33	     */
    34	    public static int format(int points) {
    35	        if (points >= 6) {
    36	            return 4;
    37	        }
    38	        if (points >= 4) {
    39	            return 3;
    40	        }
    41	        if (points >= 2) {
    42	            return 2;
    43	        }
    44	        return 1;
    45	    }
    46	}
