    24	public final class MembershipNumberFormatter {
    25	
    26	    private MembershipNumberFormatter() {
    27	    }
    28	
    29	    /**
    30	     * Format a membership number as {@code "<customerCode>-M<YY>"}, where {@code YY} is the last
    31	     * two digits of the registration date's {@link FiscalYear fiscal year}, zero-padded (for
    32	     * example {@code "SMI-0007-M26"}).
    33	     *
    34	     * @param customerCode     the owner's customer code
    35	     * @param registrationDate the owner's registration date
    36	     * @return the formatted membership number, or {@code null} if either input is {@code null}
    37	     */
    38	    public static String format(String customerCode, LocalDate registrationDate) {
    39	        if (customerCode == null || registrationDate == null) {
    40	            return null;
    41	        }
    42	        return String.format("%s-M%02d", customerCode, FiscalYear.startingYear(registrationDate) % 100);
    43	    }
    44	}
