    17	package org.springframework.samples.petclinic.util;
    18	
    19	import org.springframework.samples.petclinic.model.Owner;
    20	
    21	/**
    22	 * Derives an owner's {@code identityKey}, the single value that drives duplicate detection.
    23	 *
    24	 * <p>The key is the SHA-256 hex digest of the owner's already-normalized telephone, already
    25	 * lower-cased email and the {@link Soundex Soundex code} of the last name, joined as
    26	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. Two owners are hard
    27	 * duplicates only when their <em>whole</em> keys are equal: because the telephone is part of the
    28	 * key, two members of the same household with different telephones derive different keys and are
    29	 * both allowed (they are instead flagged as a soft match).
    30	 */
    31	public final class OwnerIdentityKey {
    32	
    33	    private static final String SEPARATOR = "|";
    34	
    35	    private OwnerIdentityKey() {
    36	    }
    37	
    38	    /**
    39	     * Compute the identity key for the given owner from its stored (already normalized) telephone
    40	     * and email and the Soundex code of its last name. A {@code null} telephone or email
    41	     * contributes an empty component.
    42	     *
    43	     * @param owner the owner to derive the key for
    44	     * @return the owner's identity key as a 64-character lower-case hex string
    45	     */
    46	    public static String of(Owner owner) {
    47	        String raw = orEmpty(owner.getTelephone())
    48	            + SEPARATOR + orEmpty(owner.getEmail())
    49	            + SEPARATOR + Soundex.encode(owner.getLastName());
    50	        return Sha256.hex(raw);
    51	    }
    52	
    53	    private static String orEmpty(String value) {
    54	        return value == null ? "" : value;
    55	    }
    56	}
