    20	
    21	/**
    22	 * Derives an owner's tenure: the number of whole {@link FiscalYear fiscal years} elapsed since their
    23	 * registration date.
    24	 */
    25	public final class OwnerTenure {
    26	
    27	    private OwnerTenure() {
    28	    }
    29	
    30	    /**
    31	     * Return the owner's tenure in whole fiscal years, measured from their registration date to
    32	     * today. A missing registration date, or one that has not yet arrived, yields a tenure of
    33	     * {@code 0}.
    34	     *
    35	     * @param registrationDate the date the owner was registered, may be {@code null}
    36	     * @return the tenure in elapsed fiscal years, never negative
    37	     */
    38	    public static int inFiscalYears(LocalDate registrationDate) {
    39	        if (registrationDate == null) {
    40	            return 0;
    41	        }
    42	        return FiscalYear.elapsed(registrationDate, LocalDate.now());
    43	    }
    44	}
