   297	    /**
   298	     * Reject creating an owner whose whole {@link OwnerIdentityKey identity key} already belongs to
   299	     * another active owner. Because the telephone is part of the key, only an existing owner sharing
   300	     * every key component (normalized telephone, lower-cased email and the last name's Soundex code)
   301	     * is a hard duplicate; telephone equality remains a prerequisite, so it prefilters the candidates.
   302	     */
   303	    private void rejectIdentityCollision(Owner owner) {
   304	        String identityKey = OwnerIdentityKey.of(owner);
   305	        boolean collides = ownerRepository.findByTelephone(owner.getTelephone()).stream()
   306	            .filter(ClinicServiceImpl::isActive)
   307	            .anyMatch(existing -> identityKey.equals(OwnerIdentityKey.of(existing)));
   308	        if (collides) {
   309	            throw new DuplicateOwnerException(identityKey);
   310	        }
   311	    }
