   313	    /**
   314	     * Whether an existing owner is still active, i.e. has not been soft-deleted. Soft-deleted owners
   315	     * are retained for history but ignored by the create-time duplicate and identity checks.
   316	     */
   317	    private static boolean isActive(Owner owner) {
   318	        return !Boolean.TRUE.equals(owner.getDeleted());
   319	    }
