   321	    /**
   322	     * Build the new owner's {@code customerCode} and de-duplicate it against existing owners. The
   323	     * base code is derived from the owner's locality, telephone and last name; if it already belongs
   324	     * to another owner it is suffixed with the smallest {@code "-<n>"} (n &gt;= 2) that is still free.
   325	     */
   326	    private String assignCustomerCode(Owner owner) {
   327	        String baseCode = CustomerCodeGenerator.format(
   328	            LocalityResolver.resolve(owner.getCity(), owner.getPostcode()),
   329	            owner.getTelephone(), owner.getLastName());
   330	        Set<String> takenCodes = ownerRepository.findByCustomerCodeStartingWith(baseCode).stream()
   331	            .map(Owner::getCustomerCode)
   332	            .collect(Collectors.toSet());
   333	        return CustomerCodeGenerator.deduplicate(baseCode, takenCodes::contains);
   334	    }
