   336	    /**
   337	     * Flag the new owner as a possible (soft) duplicate of an existing owner whose identity key
   338	     * <em>differs</em> but whose last name shares the same Soundex code and whose postcode is equal.
   339	     * The new owner is still created; {@code possibleDuplicate} is set to whether such a match exists
   340	     * and {@code possibleDuplicateOf} to the matching owner's id (the lowest when several match), or
   341	     * {@code null} when there is no match.
   342	     *
   343	     * <p>An owner that explicitly declares {@code sharesHousehold} is a <em>declared</em> household
   344	     * member rather than a suspected duplicate, so it is never flagged.
   345	     */
   346	    private void flagPossibleDuplicate(Owner owner, boolean sharesHousehold) {
   347	        Owner match = sharesHousehold ? null : findSoftMatchCandidates(owner).stream()
   348	            .min(Comparator.comparingInt(Owner::getId))
   349	            .orElse(null);
   350	        owner.setPossibleDuplicate(match != null);
   351	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
   352	    }
