   354	    /**
   355	     * Find the existing active owners that are a soft match for the new owner: those sharing its
   356	     * postcode and its last name's {@link org.springframework.samples.petclinic.util.Soundex Soundex}
   357	     * code, but deriving a <em>different</em> {@link OwnerIdentityKey identity key} (an equal key is a
   358	     * hard duplicate, rejected earlier). An owner without a postcode has no soft-match candidates.
   359	     */
   360	    private List<Owner> findSoftMatchCandidates(Owner owner) {
   361	        if (owner.getPostcode() == null) {
   362	            return List.of();
   363	        }
   364	        String soundex = Soundex.encode(owner.getLastName());
   365	        String identityKey = OwnerIdentityKey.of(owner);
   366	        return ownerRepository.findByPostcode(owner.getPostcode()).stream()
   367	            .filter(ClinicServiceImpl::isActive)
   368	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName())))
   369	            .filter(existing -> !identityKey.equals(OwnerIdentityKey.of(existing)))
   370	            .toList();
   371	    }
